// NarrowBodyData_Deep — every non-[local] field, deep encodings: full state for
// client-side prediction
export class NarrowBodyData_Deep {
  constructor() {
    this.Position = new FixedVec();
    this.Rotation = new FixedQuat();
    this.Velocity = new FixedVec();
  }
}

// NarrowBodyData_Shallow — the [interpolate] fields on the quantized wire: the
// implementation detail on the way to interpolation on the client
export class NarrowBodyData_Shallow {
  constructor() {
    // position: FixedVec narrowed to 8 fractional bits (quantize = 256) — per-component
    // quantized units; bounds are the component's whole-unit [min, max] scaled
    this.PositionX = 0; // in [-25600000, 25600000]
    this.PositionY = 0; // in [-25600000, 25600000]
    this.PositionZ = 0; // in [-25600000, 25600000]
    // rotation: FixedQuat narrowed to 10 fractional bits (quantize = 1024) — per-component
    // quantized units; bounds are the component's whole-unit [min, max] scaled
    this.RotationX = 0; // in [-1024, 1024]
    this.RotationY = 0; // in [-1024, 1024]
    this.RotationZ = 0; // in [-1024, 1024]
    this.RotationW = 0; // in [-1024, 1024]
    this.Velocity = new FixedVec();
  }
}

// NarrowBodyData_Interpolate — the same fields in interpolate storage: projected
// fields stay in the wire integer domain and snap-interpolate; quantized
// composites store continuous (SPEC §4.8 rule 5)
export class NarrowBodyData_Interpolate {
  constructor() {
    this.Position = new FixedVec();
    this.Rotation = new FixedQuat();
    this.Velocity = new FixedVec();
  }
}

export const NarrowBodyData_DeepMaxBits = 332;
export const NarrowBodyData_DeepMaxBytes = 48; // rounded up to the 8-byte write-buffer granularity

export function WriteNarrowBodyData_Deep(stream, value) {
  if (!WriteFixedVec(stream, value.Position)) {
    return false;
  }
  if (!WriteFixedQuat(stream, value.Rotation)) {
    return false;
  }
  if (!WriteFixedVec(stream, value.Velocity)) {
    return false;
  }
  return true;
}

export function ReadNarrowBodyData_Deep(stream, value) {
  if (!ReadFixedVec(stream, value.Position)) {
    return false;
  }
  if (!ReadFixedQuat(stream, value.Rotation)) {
    return false;
  }
  if (!ReadFixedVec(stream, value.Velocity)) {
    return false;
  }
  return true;
}

export const NarrowBodyData_ShallowMaxBits = 228;
export const NarrowBodyData_ShallowMaxBytes = 32; // rounded up to the 8-byte write-buffer granularity

export function WriteNarrowBodyData_Shallow(stream, value) {
  if (!Number.isInteger(value.PositionX) || value.PositionX < -25600000 || value.PositionX > 25600000) { // out-of-contract writes are refused, not wrapped
    return false;
  }
  NUMBER_SCRATCH.value = ((value.PositionX >>> 0) - (-25600000 >>> 0)) >>> 0;
  if (!stream.serializeBits(NUMBER_SCRATCH, 26)) {
    return false;
  }
  if (!Number.isInteger(value.PositionY) || value.PositionY < -25600000 || value.PositionY > 25600000) { // out-of-contract writes are refused, not wrapped
    return false;
  }
  NUMBER_SCRATCH.value = ((value.PositionY >>> 0) - (-25600000 >>> 0)) >>> 0;
  if (!stream.serializeBits(NUMBER_SCRATCH, 26)) {
    return false;
  }
  if (!Number.isInteger(value.PositionZ) || value.PositionZ < -25600000 || value.PositionZ > 25600000) { // out-of-contract writes are refused, not wrapped
    return false;
  }
  NUMBER_SCRATCH.value = ((value.PositionZ >>> 0) - (-25600000 >>> 0)) >>> 0;
  if (!stream.serializeBits(NUMBER_SCRATCH, 26)) {
    return false;
  }
  if (!Number.isInteger(value.RotationX) || value.RotationX < -1024 || value.RotationX > 1024) { // out-of-contract writes are refused, not wrapped
    return false;
  }
  NUMBER_SCRATCH.value = ((value.RotationX >>> 0) - (-1024 >>> 0)) >>> 0;
  if (!stream.serializeBits(NUMBER_SCRATCH, 12)) {
    return false;
  }
  if (!Number.isInteger(value.RotationY) || value.RotationY < -1024 || value.RotationY > 1024) { // out-of-contract writes are refused, not wrapped
    return false;
  }
  NUMBER_SCRATCH.value = ((value.RotationY >>> 0) - (-1024 >>> 0)) >>> 0;
  if (!stream.serializeBits(NUMBER_SCRATCH, 12)) {
    return false;
  }
  if (!Number.isInteger(value.RotationZ) || value.RotationZ < -1024 || value.RotationZ > 1024) { // out-of-contract writes are refused, not wrapped
    return false;
  }
  NUMBER_SCRATCH.value = ((value.RotationZ >>> 0) - (-1024 >>> 0)) >>> 0;
  if (!stream.serializeBits(NUMBER_SCRATCH, 12)) {
    return false;
  }
  if (!Number.isInteger(value.RotationW) || value.RotationW < -1024 || value.RotationW > 1024) { // out-of-contract writes are refused, not wrapped
    return false;
  }
  NUMBER_SCRATCH.value = ((value.RotationW >>> 0) - (-1024 >>> 0)) >>> 0;
  if (!stream.serializeBits(NUMBER_SCRATCH, 12)) {
    return false;
  }
  if (!WriteFixedVec(stream, value.Velocity)) {
    return false;
  }
  return true;
}

export function ReadNarrowBodyData_Shallow(stream, value) {
  if (!stream.serializeInt(NUMBER_SCRATCH, -25600000, 25600000)) {
    return false;
  }
  value.PositionX = NUMBER_SCRATCH.value;
  if (!stream.serializeInt(NUMBER_SCRATCH, -25600000, 25600000)) {
    return false;
  }
  value.PositionY = NUMBER_SCRATCH.value;
  if (!stream.serializeInt(NUMBER_SCRATCH, -25600000, 25600000)) {
    return false;
  }
  value.PositionZ = NUMBER_SCRATCH.value;
  if (!stream.serializeInt(NUMBER_SCRATCH, -1024, 1024)) {
    return false;
  }
  value.RotationX = NUMBER_SCRATCH.value;
  if (!stream.serializeInt(NUMBER_SCRATCH, -1024, 1024)) {
    return false;
  }
  value.RotationY = NUMBER_SCRATCH.value;
  if (!stream.serializeInt(NUMBER_SCRATCH, -1024, 1024)) {
    return false;
  }
  value.RotationZ = NUMBER_SCRATCH.value;
  if (!stream.serializeInt(NUMBER_SCRATCH, -1024, 1024)) {
    return false;
  }
  value.RotationW = NUMBER_SCRATCH.value;
  if (!ReadFixedVec(stream, value.Velocity)) {
    return false;
  }
  return true;
}

// QuantizeNarrowBody maps NarrowBodyData_Interpolate into NarrowBodyData_Shallow — the
// hand-written Quantize(), generated (SPEC §4.8).
export function QuantizeNarrowBody(input, output) {
  {
    const raw = input.Position.X;
    output.PositionX = Number(raw >= 0n ? (raw + 128n) >> 8n : -((-raw + 128n) >> 8n));
  }
  {
    const raw = input.Position.Y;
    output.PositionY = Number(raw >= 0n ? (raw + 128n) >> 8n : -((-raw + 128n) >> 8n));
  }
  {
    const raw = input.Position.Z;
    output.PositionZ = Number(raw >= 0n ? (raw + 128n) >> 8n : -((-raw + 128n) >> 8n));
  }
  {
    const raw = input.Rotation.X;
    output.RotationX = raw >= 0 ? Math.floor((raw + 524288) / 1048576) : -Math.floor((-raw + 524288) / 1048576);
  }
  {
    const raw = input.Rotation.Y;
    output.RotationY = raw >= 0 ? Math.floor((raw + 524288) / 1048576) : -Math.floor((-raw + 524288) / 1048576);
  }
  {
    const raw = input.Rotation.Z;
    output.RotationZ = raw >= 0 ? Math.floor((raw + 524288) / 1048576) : -Math.floor((-raw + 524288) / 1048576);
  }
  {
    const raw = input.Rotation.W;
    output.RotationW = raw >= 0 ? Math.floor((raw + 524288) / 1048576) : -Math.floor((-raw + 524288) / 1048576);
  }
  output.Velocity.X = input.Velocity.X;
  output.Velocity.Y = input.Velocity.Y;
  output.Velocity.Z = input.Velocity.Z;
}

// UnquantizeNarrowBody maps NarrowBodyData_Shallow back into NarrowBodyData_Interpolate.
export function UnquantizeNarrowBody(input, output) {
  output.Position.X = BigInt(input.PositionX) << 8n;
  output.Position.Y = BigInt(input.PositionY) << 8n;
  output.Position.Z = BigInt(input.PositionZ) << 8n;
  output.Rotation.X = input.RotationX * 1048576;
  output.Rotation.Y = input.RotationY * 1048576;
  output.Rotation.Z = input.RotationZ * 1048576;
  output.Rotation.W = input.RotationW * 1048576;
  output.Velocity.X = input.Velocity.X;
  output.Velocity.Y = input.Velocity.Y;
  output.Velocity.Z = input.Velocity.Z;
}

// MessageStorage is the pre-allocated home a read message lands in — the JS
// stand-in for the C++ tagged union (SPEC §6.1: storage never heap-allocates
// per message; fixed buffers on sender and receiver). Reuse it across reads:
// the message a read returns points into it and stays valid until the next
// read against the same storage — the union's own discipline, exactly.
export class MessageStorage {
  constructor() {
    this.LudicrousState = new LudicrousState();
  }
}

// The message tag wire: MessageType in [0, 1], minimal bits; None = 0 is a
// valid wire value meaning *no message* — the stream terminator (SPEC §4.8).
// The write folds the tag's bit count at generation time (byte-identical to
// the ranged form); a tag outside the set is refused — bool alone.
export function WriteMessageType(stream, value) {
  if (!Number.isInteger(value) || value < 0 || value > 1) {
    return false;
  }
  NUMBER_SCRATCH.value = value;
  return stream.serializeBits(NUMBER_SCRATCH, 1);
}

// ReadMessageType reads the tag into a { value } holder — the runtime's own
// ref convention (JS has no out parameters).
export function ReadMessageType(stream, value) {
  if (!stream.serializeInt(NUMBER_SCRATCH, 0, 1)) {
    return false;
  }
  value.value = NUMBER_SCRATCH.value;
  return true;
}

// The message-level bound: the tag plus the largest message (SPEC §6.1);
// MessageMaxBytes is rounded up to the 8-byte write-buffer granularity.
export const MessageMaxBits = 1206;
export const MessageMaxBytes = 152;

// WriteMessage: null is the None terminator; a value outside the generated
// class set (undefined included) writes NOTHING — a tag with no payload
// would desynchronize the stream — and the refusal is bool alone.
export function WriteMessage(stream, message) {
  if (message === null) {
    return WriteMessageType(stream, MessageType.None); // the stream terminator (SPEC §4.8)
  }
  if (message instanceof LudicrousState) {
    if (!WriteMessageType(stream, MessageType.LudicrousState)) {
      return false;
    }
    return WriteLudicrousState(stream, message);
  }
  return false; // not a generated message class; nothing was written
}

// ReadMessage lands in the caller's MessageStorage and hands the message
// back through the { value } holder: null under a None tag (the terminator
// — a success), the storage's instance otherwise. The returned message
// points INTO storage and stays valid until the next read against it.
export function ReadMessage(stream, storage, message) {
  message.value = null;
  if (!ReadMessageType(stream, NUMBER_SCRATCH)) {
    return false;
  }
  // the scratch holder is consumed by the switch head before any nested
  // read runs — the holder discipline
  switch (NUMBER_SCRATCH.value) {
    case MessageType.None:
      return true; // the stream terminator (SPEC §4.8) — message stays null
    case MessageType.LudicrousState:
      ZeroLudicrousState(storage.LudicrousState); // reused storage starts from the zero form, as the union does
      if (!ReadLudicrousState(stream, storage.LudicrousState)) {
        return false;
      }
      message.value = storage.LudicrousState;
      return true;
    default:
      // unreachable: ReadMessageType bounds the tag to [0, 1] and every
      // value in range has an arm; the default keeps the verdict total
      return false;
  }
}

// The object tag wire: ObjectType in [0, 2], minimal bits; None = 0 is the
// null — the sentinel the surveyed baseline streams terminate with (SPEC §4.8).
// The write folds the tag's bit count at generation time (byte-identical to
// the ranged form); a tag outside the set is refused — bool alone.
export function WriteObjectType(stream, value) {
  if (!Number.isInteger(value) || value < 0 || value > 2) {
    return false;
  }
  NUMBER_SCRATCH.value = value;
  return stream.serializeBits(NUMBER_SCRATCH, 2);
}

// ReadObjectType reads the tag into a { value } holder — the runtime's own
// ref convention (JS has no out parameters).
export function ReadObjectType(stream, value) {
  if (!stream.serializeInt(NUMBER_SCRATCH, 0, 2)) {
    return false;
  }
  value.value = NUMBER_SCRATCH.value;
  return true;
}

